pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        bool ownerResult;
        bool nonOwnerResult;
        try c.sudicideAnyone() { nonOwnerResult = true; } catch { nonOwnerResult = false; }
        vm.prank(caller);
        try c.sudicideAnyone() { ownerResult = true; } catch { ownerResult = false; }
