pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount) public {
        address owner = address(0xdead);
        vm.deal(address(c), amount);
        vm.prank(owner);
        uint256 ownerBalanceBefore = owner.balance;
        c.sudicideAnyone();
        uint256 ownerBalanceAfter = owner.balance;
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + uint256(amount));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 fakeOwner) public {
        address owner = address(uint160(fakeOwner));
        vm.assume(owner != address(0));
        vm.prank(owner);
        try c.sudicideAnyone() {
            // if the call succeeds, the contract must be destroyed
            uint256 codeSize;
            assembly {
                codeSize := extcodesize(c)
            }
            assertTrue(codeSize == 0 || owner != c.__owner());
        } catch {
            // if it reverts, owner must not be the actual owner
            // We can't read __owner because it's private, but we can verify that
            // the call reverted, which is acceptable for a non-owner.
            assertTrue(true);
        }
    }
}

